// To find the lowest point of a curve: look at the slope where you stand,
// take a step DOWNHILL, repeat. The learning rate is the step size.
std::vector<double> gradientDescent(double start, double learningRate, int steps) {
    std::vector<double> xs = {start};
    double x = start;
    for (int i = 0; i < steps; ++i) {
        x -= learningRate * slope(x);  // slope > 0: go left; slope < 0: go right
        xs.push_back(x);
    }
    return xs;
}

backtrack.nqueens.code:
// Backtracking: try a choice, go deeper, and UNDO it if it leads nowhere.
static bool safe(const std::vector<int>& colOf, int row, int col) {
    for (int r = 0; r < row; ++r) {
        // same column, or same diagonal (row distance == column distance)
        if (colOf[r] == col || std::abs(colOf[r] - col) == row - r) return false;
    }
    return true;
}

static bool place(int row, int n, std::vector<int>& colOf) {
    if (row == n) return true;  // every row has a queen: solved
    for (int col = 0; col < n; ++col) {
        if (!safe(colOf, row, col)) continue;
        colOf[row] = col;  // try it
        if (place(row + 1, n, colOf)) return true;
        colOf[row] = -1;  // dead end: undo and try the next column
    }
    return false;
}

bool solveQueens(int n, std::vector<int>& colOf) {
    colOf.assign(n, -1);
    return place(0, n, colOf);
}

