// dp[x] = the fewest coins that make amount x. Build it up from 0:
// small answers are reused to build bigger ones (that's dynamic programming).
int coinChange(const std::vector<int>& coins, int amount) {
    const int INF = amount + 1;  // more coins than any real answer could need
    std::vector<int> dp(amount + 1, INF);
    dp[0] = 0;  // zero coins make zero
    for (int x = 1; x <= amount; ++x) {
        for (int c : coins) {
            if (c <= x) dp[x] = std::min(dp[x], dp[x - c] + 1);  // use coin c last
        }
    }
    return dp[amount] >= INF ? -1 : dp[amount];
}

dp.lcs.code:
// Longest common subsequence: dp[i][j] = answer for the first i letters
// of a and the first j letters of b.
int lcsLength(const std::string& a, const std::string& b) {
    std::vector<std::vector<int>> dp(a.size() + 1, std::vector<int>(b.size() + 1, 0));
    for (std::size_t i = 1; i <= a.size(); ++i) {
        for (std::size_t j = 1; j <= b.size(); ++j) {
            if (a[i - 1] == b[j - 1]) dp[i][j] = dp[i - 1][j - 1] + 1;  // letters match: extend
            else dp[i][j] = std::max(dp[i - 1][j], dp[i][j - 1]);  // drop one letter
        }
    }
    return dp[a.size()][b.size()];
}

graph.bfs_grid.code:
// Shortest path on a grid where every step costs 1 = breadth-first search.
// BFS explores in rings: everything 1 step away, then 2 steps, then 3...
std::vector<Cell> bfsPath(const std::vector<std::string>& grid, Cell start, Cell goal) {
    const int rows = static_cast<int>(grid.size()), cols = static_cast<int>(grid[0].size());
    std::vector<std::vector<int>> dist(rows, std::vector<int>(cols, -1));
    std::vector<std::vector<Cell>> parent(rows, std::vector<Cell>(cols, {-1, -1}));
    std::queue<Cell> todo;
    dist[start.first][start.second] = 0;
    todo.push(start);
    const int dr[4] = {-1, 1, 0, 0}, dc[4] = {0, 0, -1, 1};
    while (!todo.empty()) {
        const auto [r, c] = todo.front();
        todo.pop();
        if (Cell{r, c} == goal) break;  // the first time we reach it is the shortest way
        for (int d = 0; d < 4; ++d) {
            const int nr = r + dr[d], nc = c + dc[d];
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
            if (grid[nr][nc] == '#' || dist[nr][nc] != -1) continue;  // wall, or already seen
            dist[nr][nc] = dist[r][c] + 1;
            parent[nr][nc] = {r, c};  // remember how we got here
            todo.push({nr, nc});
        }
    }
    std::vector<Cell> path;  // walk the parents back from the goal
    if (dist[goal.first][goal.second] == -1) return path;
    for (Cell at = goal; at != Cell{-1, -1}; at = parent[at.first][at.second]) path.push_back(at);
    std::reverse(path.begin(), path.end());
    return path;
}

graph.dijkstra.code:
// Shortest paths when edges have different costs. Always settle the
// closest unsettled node next, using a min-priority-queue.
std::vector<long long> dijkstra(const std::vector<std::vector<std::pair<int, int>>>& adj,
                                int source) {
    const long long INF = LLONG_MAX;
    std::vector<long long> dist(adj.size(), INF);
    using Item = std::pair<long long, int>;  // (distance so far, node)
    std::priority_queue<Item, std::vector<Item>, std::greater<>> pq;  // smallest distance on top
    dist[source] = 0;
    pq.push({0, source});
    while (!pq.empty()) {
        const auto [d, u] = pq.top();
        pq.pop();
        if (d > dist[u]) continue;  // an old, longer entry: skip it
        for (const auto& [v, w] : adj[u]) {
            if (dist[u] + w < dist[v]) {  // found a shorter way to v
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }
    return dist;
}

graph.topo_sort.code:
// Kahn's algorithm: repeatedly take something that has no unmet
// prerequisites (in-degree 0), output it, and "cross it off" for others.
std::vector<std::string> topoSort(const std::vector<std::string>& nodes,
                                  const std::vector<std::pair<std::string, std::string>>& edges,
                                  Recorder& rec) {
    std::map<std::string, int> indegree;            // how many things must come first
    std::map<std::string, std::vector<std::string>> after;
    for (const auto& n : nodes) indegree[n] = 0;
    for (const auto& [a, b] : edges) {
        after[a].push_back(b);
        ++indegree[b];
    }
    std::deque<std::string> ready;  // in-degree 0: can go right now
    for (const auto& n : nodes)
        if (indegree[n] == 0) ready.push_back(n);
    std::vector<std::string> order;
    while (!ready.empty()) {
        const std::string n = ready.front();
        ready.pop_front();
        order.push_back(n);
        for (const auto& next : after[n]) {
            if (--indegree[next] == 0) ready.push_back(next);  // last blocker gone
        }
    }
    if (order.size() != nodes.size()) return {};  // leftovers wait on each other: a cycle
    return order;
}

