// A hash set with "separate chaining": key -> bucket index -> a short list.
std::size_t HashSet::index(int key) const {
    const auto m = static_cast<long long>(buckets_.size());
    return static_cast<std::size_t>(((key % m) + m) % m);  // modulo that is never negative
}

bool HashSet::contains(int key) const {
    for (int k : buckets_[index(key)])  // only ONE short list is searched
        if (k == key) return true;
    return false;
}

bool HashSet::insert(int key) {
    if (contains(key)) return false;
    // Keep the load factor (keys / buckets) at most 0.75, so chains stay short.
    if ((size_ + 1) * 4 > buckets_.size() * 3) rehash(buckets_.size() * 2 + 1);
    buckets_[index(key)].push_back(key);
    ++size_;
    return true;
}

void HashSet::rehash(std::size_t bucketCount) {
    std::vector<std::vector<int>> old = std::move(buckets_);
    buckets_.assign(bucketCount, {});
    for (const auto& chain : old)
        for (int k : chain) buckets_[index(k)].push_back(k);  // every key moves to its NEW bucket
}

heap.binary_heap.code:
// A min-heap stored in a plain array: the children of i are 2i+1 and 2i+2,
// the parent of i is (i-1)/2. Rule: every parent <= its children.
void heapPush(std::vector<int>& heap, int value) {
    heap.push_back(value);  // add at the end...
    std::size_t i = heap.size() - 1;
    while (i > 0 && heap[(i - 1) / 2] > heap[i]) {  // ...then bubble up
        std::swap(heap[(i - 1) / 2], heap[i]);
        i = (i - 1) / 2;
    }
}

int heapPop(std::vector<int>& heap) {
    const int top = heap.front();
    heap.front() = heap.back();  // move the last leaf to the root...
    heap.pop_back();
    std::size_t i = 0;
    while (true) {  // ...then sink it down
        const std::size_t l = 2 * i + 1, r = 2 * i + 2;
        std::size_t smallest = i;
        if (l < heap.size() && heap[l] < heap[smallest]) smallest = l;
        if (r < heap.size() && heap[r] < heap[smallest]) smallest = r;
        if (smallest == i) break;
        std::swap(heap[i], heap[smallest]);
        i = smallest;
    }
    return top;
}

