// The review queue is a priority queue (a heap): the most overdue card
// first; among equally overdue cards, the lowest box (weakest) first.
std::vector<std::string> Progress::dueReviews(long today, std::size_t limit) const {
    std::lock_guard lock(mutex_);
    using Item = std::tuple<long, int, std::string>;  // due day, box, card id
    auto later = [](const Item& a, const Item& b) { return a > b; };  // makes a MIN-heap
    std::priority_queue<Item, std::vector<Item>, decltype(later)> heap(later);
    for (const auto& [id, card] : data_.cards) {
        if (card.due <= today) heap.emplace(card.due, card.box, id);
    }
    std::vector<std::string> out;
    while (!heap.empty() && out.size() < limit) {
        out.push_back(std::get<2>(heap.top()));
        heap.pop();
    }
    return out;
}

list.cycle.code:
// Floyd's "tortoise and hare": if there is a loop, the fast pointer
// eventually laps the slow one, like runners on a circular track.
bool hasCycle(ListNode* head, Recorder& rec) {
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast != nullptr && fast->next != nullptr) {
        slow = slow->next;        // 1 step
        fast = fast->next->next;  // 2 steps
        if (slow == fast) return true;  // they met: there is a loop
    }
    return false;  // fast reached the end: no loop
}

list.reverse.code:
ListNode* reverseList(ListNode* head, Recorder& rec) {
    ListNode* prev = nullptr;  // the reversed part starts empty
    ListNode* curr = head;     // the part still to reverse
    while (curr != nullptr) {
        ListNode* next = curr->next;  // 1. remember the rest of the list
        curr->next = prev;  // 2. flip the arrow backwards
        prev = curr;  // 3. move prev forward
        curr = next;  // 4. move curr forward
    }
    return prev;  // the old tail is the new head
}

