// A fixed-size circular queue: no allocation, ever. head = next to read,
// tail = next free slot; both wrap around with % N.
template <typename T, std::size_t N>
class RingQueue {
public:
    bool push(const T& v) {
        if (count_ == N) return false;  // full: the caller decides what to do
        items_[tail_] = v;
        tail_ = (tail_ + 1) % N;
        ++count_;
        return true;
    }
    bool pop(T& out) {
        if (count_ == 0) return false;
        out = items_[head_];
        head_ = (head_ + 1) % N;
        --count_;
        return true;
    }
    std::size_t size() const { return count_; }
    std::size_t head() const { return head_; }
    std::size_t tail() const { return tail_; }
    const std::array<T, N>& raw() const { return items_; }

private:
    std::array<T, N> items_{};
    std::size_t head_ = 0, tail_ = 0, count_ = 0;
};

