// "243 ways" on 5 reels x 3 rows: any position on reel 1, then any on
// reel 2, ... (3 x 3 x 3 x 3 x 3 = 243 paths). A symbol pays for every
// path that matches from the left, so we MULTIPLY the matches per reel.
std::vector<WaysResult> evaluateWays(const ReelGame& g, const Screen& s) {
    std::vector<WaysResult> wins;
    for (int sym = 0; sym < static_cast<int>(g.symbols.size()); ++sym) {
        if (sym == g.wild) continue;
        long long ways = 1;
        int reels = 0;
        for (std::size_t k = 0; k < g.reels.size(); ++k) {
            int matches = 0;
            for (int row = 0; row < g.rows; ++row) {
                if (s[row][k] == sym || s[row][k] == g.wild) ++matches;
            }
            if (matches == 0) break;  // the chain stops at the first reel without it
            ways *= matches;
            ++reels;
        }
        const int pay = g.paytable[sym][reels];
        if (pay > 0) wins.push_back({sym, reels, ways, pay * ways});
    }
    return wins;
}

slot.window.code:
// A reel strip is a CIRCULAR array: after the last stop comes the first.
// The % (modulo) operator does the wrap-around for us.
Screen window(const ReelGame& g, const std::vector<int>& stops) {
    Screen screen(g.rows, std::vector<int>(g.reels.size()));
    for (std::size_t reel = 0; reel < g.reels.size(); ++reel) {
        const auto& strip = g.reels[reel];
        const int len = static_cast<int>(strip.size());
        for (int row = 0; row < g.rows; ++row) {
            screen[row][reel] = strip[(stops[reel] + row) % len];
        }
    }
    return screen;
}

sort.bubble.code:
void bubbleSort(std::vector<int>& a, Recorder& rec) {
    const std::size_t n = a.size();
    for (std::size_t pass = 0; pass + 1 < n; ++pass) {
        bool swapped = false;
        for (std::size_t j = 0; j + 1 < n - pass; ++j) {
            if (a[j] > a[j + 1]) {
                std::swap(a[j], a[j + 1]);
                swapped = true;
            }
        }
        if (!swapped) break;  // nothing moved: already sorted
    }
}

sort.heap.code:
// Push a[root] down until both children are smaller (max-heap rule).
void siftDown(std::vector<int>& a, std::size_t root, std::size_t size, Recorder& rec) {
    while (true) {
        std::size_t largest = root;
        std::size_t left = 2 * root + 1, right = 2 * root + 2;
        if (left < size && a[left] > a[largest]) largest = left;
        if (right < size && a[right] > a[largest]) largest = right;
        if (largest == root) return;
        std::swap(a[root], a[largest]);
        root = largest;
    }
}

void heapSort(std::vector<int>& a, Recorder& rec) {
    const std::size_t n = a.size();
    for (std::size_t i = n / 2; i-- > 0;) siftDown(a, i, n, rec);
    for (std::size_t end = n; end-- > 1;) {
        std::swap(a[0], a[end]);  // biggest goes to the back
        siftDown(a, 0, end, rec);
    }
}

sort.insertion.code:
void insertionSort(std::vector<int>& a, Recorder& rec) {
    for (std::size_t i = 1; i < a.size(); ++i) {
        int key = a[i];  // the card we are inserting
        std::size_t j = i;
        while (j > 0 && a[j - 1] > key) {
            a[j] = a[j - 1];  // shift the bigger one right
            --j;
        }
        a[j] = key;  // drop the card into the gap
    }
}

sort.merge.code:
// Sorts a[lo, hi)  ("hi" is one past the end, like end() in the STL).
void mergeSort(std::vector<int>& a, std::size_t lo, std::size_t hi, std::vector<int>& tmp,
               Recorder& rec) {
    if (hi - lo < 2) return;  // 0 or 1 items: already sorted
    std::size_t mid = lo + (hi - lo) / 2;
    mergeSort(a, lo, mid, tmp, rec);  // sort the left half
    mergeSort(a, mid, hi, tmp, rec);  // sort the right half

    std::size_t i = lo, j = mid, k = lo;  // merge two sorted halves
    while (i < mid && j < hi) {
        if (a[i] <= a[j]) tmp[k++] = a[i++];
        else tmp[k++] = a[j++];
    }
    while (i < mid) tmp[k++] = a[i++];  // copy leftovers
    while (j < hi) tmp[k++] = a[j++];
    std::copy(tmp.begin() + lo, tmp.begin() + hi, a.begin() + lo);
}

void mergeSort(std::vector<int>& a, Recorder& rec) {
    std::vector<int> tmp(a.size());  // one buffer, reused by every merge
    mergeSort(a, 0, a.size(), tmp, rec);
}

sort.quick.code:
// Lomuto partition: the last element is the pivot.
int partition(std::vector<int>& a, int lo, int hi, Recorder& rec) {
    int pivot = a[hi];
    int store = lo;     // next slot for a value smaller than the pivot
    for (int j = lo; j < hi; ++j) {
        if (a[j] < pivot) {
            std::swap(a[store], a[j]);
            ++store;
        }
    }
    std::swap(a[store], a[hi]);  // pivot lands in its final place
    return store;
}

void quickSort(std::vector<int>& a, int lo, int hi, Recorder& rec) {
    if (lo >= hi) return;
    int p = partition(a, lo, hi, rec);
    quickSort(a, lo, p - 1, rec);  // left of the pivot
    quickSort(a, p + 1, hi, rec);  // right of the pivot
}

void quickSort(std::vector<int>& a, Recorder& rec) {
    quickSort(a, 0, static_cast<int>(a.size()) - 1, rec);
}

sort.selection.code:
void selectionSort(std::vector<int>& a, Recorder& rec) {
    const std::size_t n = a.size();
    for (std::size_t i = 0; i + 1 < n; ++i) {
        std::size_t minIdx = i;  // best candidate so far
        for (std::size_t j = i + 1; j < n; ++j) {
            if (a[j] < a[minIdx]) {
                minIdx = j;
            }
        }
        std::swap(a[i], a[minIdx]);  // put the smallest in place
    }
}

stack.balanced.code:
bool isBalanced(const std::string& text, Recorder& rec) {
    std::vector<char> stack;  // a vector makes a perfect stack: push_back / back / pop_back
    for (std::size_t i = 0; i < text.size(); ++i) {
        char c = text[i];
        if (c == '(' || c == '[' || c == '{') {
            stack.push_back(c);  // remember the opener
        } else if (c == ')' || c == ']' || c == '}') {
            if (stack.empty()) return false;  // a closer with nothing open
            char open = stack.back();
            stack.pop_back();
            bool match = (open == '(' && c == ')') || (open == '[' && c == ']') ||
                         (open == '{' && c == '}');
            if (!match) return false;
        }
    }
    return stack.empty();  // leftovers mean something was never closed
}

tree.bst.code:
// Each node OWNS its children (unique_ptr), so deleting the root frees the whole tree.
// insert takes a reference to the owning pointer, so it can fill an empty spot in place.
void bstInsert(std::unique_ptr<TreeNode>& node, int value, const TreeNode* root, Recorder& rec) {
    if (!node) {
        node = std::make_unique<TreeNode>(TreeNode{value, nullptr, nullptr});  // empty spot
        return;
    }
    if (value < node->value) bstInsert(node->left, value, root, rec);  // smaller: left subtree
    else bstInsert(node->right, value, root, rec);  // bigger or equal: right subtree
}

const TreeNode* bstFind(const TreeNode* node, int target) {
    while (node != nullptr && node->value != target) {
        node = target < node->value ? node->left.get() : node->right.get();
    }
    return node;  // nullptr if the value isn't in the tree
}

tree.traversals.code:
// Depth-first, recursively. The only difference is WHEN we visit the node.
void inorder(const TreeNode* n, std::vector<int>& out) {
    if (!n) return;
    inorder(n->left.get(), out);
    out.push_back(n->value);  // between the children: sorted order for a BST
    inorder(n->right.get(), out);
}

void preorder(const TreeNode* n, std::vector<int>& out) {
    if (!n) return;
    out.push_back(n->value);  // before the children: copy/serialise a tree
    preorder(n->left.get(), out);
    preorder(n->right.get(), out);
}

// Breadth-first: a queue visits the tree level by level.
std::vector<int> levelOrder(const TreeNode* root) {
    std::vector<int> out;
    std::queue<const TreeNode*> todo;
    if (root) todo.push(root);
    while (!todo.empty()) {
        const TreeNode* n = todo.front();
        todo.pop();
        out.push_back(n->value);
        if (n->left) todo.push(n->left.get());
        if (n->right) todo.push(n->right.get());
    }
    return out;
}
